@Test
    public void testDivide_StandardMath() {
        // (1 + 2i) / (3 + 4i)
        // = [(1*3 + 2*4) / (3^2 + 4^2)] + i[(2*3 - 1*4) / (3^2 + 4^2)]
        // = [11/25] + i[2/25] = 0.44 + 0.08i
        Complex c = new Complex(1.0, 2.0);
        Complex divisor = new Complex(3.0, 4.0);
        Complex result = c.divide(divisor);

        assertEquals(0.44, result.getReal(), EPSILON);
        assertEquals(0.08, result.getImaginary(), EPSILON);
    }

