@Test
    public void testSanitize_TruncationLogic() {
        // To trigger the truncation branch: cs.length > MAX_SANITIZED_NAME_LENGTH
        // We create a very long string.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 100; i++) {
            sb.append('a');
        }
        String longInput = sb.toString();
        String result = ArchiveUtils.sanitize(longInput);

        // The length should be exactly MAX_SANITIZED_NAME_LENGTH
        // And the last 3 characters should be '.'
        // We don't know MAX_SANITIZED_NAME_LENGTH exactly, but we can infer from the code:
        // The loop runs from MAX_SANITIZED_NAME_LENGTH - 3 to MAX_SANITIZED_NAME_LENGTH - 1
        // The length of the result should be the length of the truncated array.

        // Since we can't know the constant, we verify the suffix pattern if the string is long enough.
        // We check if the string ends with '...' (if length allows) or just contains dots at the end.
        // This test assumes the constant is small enough to be hit.
        assertTrue(result.length() > 0);
        // If the logic works, the end of the string should be '...'
        // We check the last 3 chars are dots.
        assertEquals('.', result.charAt(result.length() - 1), '.');
        assertEquals('.', result.charAt(result.length() - 2), '.');
        assertEquals('.', result.charAt(result.length() - 3), '.');
    }

