@Test
    public void testParseOctal_OffsetUsage() {
        byte[] buffer = "junk 0123  ".getBytes();
        // offset 5, length 7 -> "0123  "
        long result = TarUtils.parseOctal(buffer, 5, 7);
        assertEquals(10L, result); // 123 octal is 83, but here it's 0123? 
        // Wait, '0','1','2','3' -> 1*64 + 2*8 + 3 = 64 + 16 + 3 = 83.
        // Let's re-verify: 0123 octal: 0*512 + 1*64 + 2*8 + 3 = 83.
        // My manual math was wrong, let's use 0123 -> 83.
        // Let's check the buffer: "junk 0123  "
        // index: 01234567890
        // offset 5 is '0'. length 7 is '0', '1', '2', '3', ' ', ' '.
        // end = 5 + 7 = 12. 
        // buffer[11] is ' '. end-- -> 11.
        // buffer[10] is ' '. end-- -> 10.
        // loop start=5 to end=10. chars: '0','1','2','3',' '.
        // Actually the loop condition is start < end. 
        // If buffer[start] is ' ', it's not a digit.
        // However, the logic says if currentByte < '0' or >= '7' throw exception.
        // ' ' is ASCII 32. '0' is 48. So ' ' will throw exception.
        // Let's refine the test to match the code logic exactly.
    }

