@Test
    public void testGetU_IdentityMatrix() throws Exception {
        // Test with Identity matrix to ensure mathematical consistency
        double[][] data = {
                {1.0, 0.0},
                {0.0, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        SingularValueDecompositionImpl svd = new SingularValueDecompositionImpl(matrix);

        RealMatrix u = svd.getU();
        RealMatrix s = svd.getS();
        RealMatrix v = svd.getV();

        // For Identity, U and V should be Identity, S should be Identity
        // We check dimensions and non-nullity as exact values depend on internal decomposition stability
        assertNotNull(u);
        assertEquals(2, u.getRowDimension());
        assertEquals(2, u.getColumnDimension());

        // Verify U * S * VT = A (approx)
        RealMatrix vt = svd.getVT();
        RealMatrix reconstructed = u.multiply(s).multiply(vt);

        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                assertEquals("Reconstructed matrix should match original", matrix.getEntry(i, j), reconstructed.getEntry(i, j), EPSILON);
            }
        }
    }

