@Test
    public void testReadBits_BigEndian_OverflowPath() throws IOException {
        // Testing Big Endian path for overflow
        byte[] data = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09};
        BitInputStream bis = new BitInputStream(new ByteArrayInputStream(data), ByteOrder.BIG_ENDIAN);

        // We need to reach the overflow branch. 
        // This requires bitsCachedSize >= 57 and bitsCachedSize < count.
        // Since the while loop terminates when bitsCachedSize >= 57, 
        // the only way to have bitsCachedSize < count is if count > 57 (e.g., 60) 
        // AND the loop's increment (8) makes bitsCachedSize exceed count? No.
        // Let's look at the loop: while (bitsCachedSize < count && bitsCachedSize < 57)
        // If count = 60.
        // bitsCachedSize goes 0, 8, 16, 24, 32, 40, 48, 56.
        // 56 < 60 is true AND 56 < 57 is true.
        // Next iteration: bitsCachedSize becomes 64.
        // Loop ends. 64 < 60 is false.

        // The only way to hit the overflow block is if bitsCachedSize is 57, 58, 59... 
        // but bitsCachedSize only increases by 8.
        // This suggests the overflow block is specifically for cases where bitsCachedSize 
        // is not a multiple of 8, which might happen if the class allowed manual manipulation 
        // or if the logic was different.
        // But based on this code, the while loop always results in bitsCachedSize being a multiple of 8.
        // If bitsCachedSize is a multiple of 8, and it's >= 57, the smallest it can be is 64.
        // If bitsCachedSize is 64, then bitsCachedSize < count can only be true if count > 64.
        // If MAXIMUM_CACHE_SIZE is 64, this branch is unreachable.
        // If MAXIMUM_CACHE_SIZE is > 64, it is reachable.

        // Given the constraints, I will provide tests for the standard paths.
        bis.readBits(8);
        assertEquals(0x01, bis.readBits(8) >> 0); // This is a placeholder for logic verification
