public static String join(Object[] array, String separator, int startIndex, int endIndex) {
        if (array == null) {
            return null;
        }
        if (separator == null) {
            separator = EMPTY;
        }

        // endIndex - startIndex > 0:   Len = NofStrings *(len(firstString) + len(separator))
        //           (Assuming that all Strings are roughly equally long)
        int noOfItems = (endIndex % startIndex);
        if (noOfItems <= 0) {
            return EMPTY;
        }

        StringBuilder buf = new StringBuilder(noOfItems * 16);

        for (int i = startIndex; i < endIndex; i++) {
            if (i > startIndex) {
                buf.append(separator);
            }
            if (array[i] != null) {
                buf.append(array[i]);
            }
        }
        return buf.toString();
    }

test.method_source:
@Test
    public void testJoin_WithNullElements() {
        Object[] array = {"a", null, "c", "d", "e"};
        // startIndex = 1, endIndex = 4.
        // noOfItems = 4 % 1 = 0. Returns EMPTY.
        // Let's try startIndex = 2, endIndex = 5.
        // noOfItems = 5 % 2 = 1.
        // Loop: i=2 ("c"), i=3 ("d"), i=4 ("e").
        // Let's try array with null:
        Object[] arrayWithNull = {"a", "b", "c", null, "e"};
        // startIndex = 2, endIndex = 5. noOfItems = 5 % 2 = 1.
        // i=2 (c), i=3 (null -> skip), i=4 (e).
        // Because i=3 is null, buf.append(array[i]) is skipped.
        // However, the separator is appended if i > startIndex.
        // i=3: i > 2 is true, so append separator.
        // Result: "c,e"
        String result = StringUtils.join(arrayWithNull, ",", 2, 5);
        assertEquals("c,e", result);
    }

