@Test
    public void testExpandCurrentSegment_ManualSetupForBranch() throws Exception {
        // To cover the 'if (newLen > MAX_SEGMENT_LEN)' branch:
        // We need newLen > MAX_SEGMENT_LEN.
        // Let's force MAX_SEGMENT_LEN to 1 using reflection.
        try {
            setMaxSegmentLen(1);
        } catch (Exception e) {
            // If reflection fails due to security/final, we skip this specific branch test
            return;
        }

        // If len = 4, len >> 1 = 2. newLen = 4 / 2 = 2.
        // 2 > 1 (MAX_SEGMENT_LEN), so it enters the if.
        // newLen = 4 + (4 >> 2) = 4 + 1 = 5.

        setInternalSegment(new char[4]);
        char[] result = textBuffer.expandCurrentSegment();

        Assert.assertEquals(5, result.length);
    }

