    public void testAddYears_LeapYearEdgeCase() {
        // Test adding years to a leap day (Feb 29)
        // Adding 1 year to 2024-02-29 should result in 2025-02-28
        MutableDateTime dt = new MutableDateTime(2024, 2, 29, 0, 0, 0, 0);
